entries[282803] = { ["name"] = "Geätztes Gefäß des düsteren Kämpfers", ["text"] = "Wirken in 3 sek.\nReagenzien:\nLeichtes Pergament (50), Ultramarinblaue Tinte (50), Grünliche Tinte (15), Expulsom (3)\nStellt ein geätztes Gefäß des düsteren Kämpfers her.\nBerufsausbilder:\nInschriftenkunde von Battle for Azeroth (115)\nKosten:\n17\n50\n\nHorde\nGeätztes Gefäß des düsteren Kämpfers\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+10 Intelligenz\n+5 Ausdauer\n50\nAllianz\nGeätztes Gefäß des düsteren Kämpfers\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+10 Intelligenz\n+5 Ausdauer\n50" }
