entries[282825] = { ["name"] = "Streubombenhagel", ["text"] = "100 Meter Reichweite\nSofort\nEure Zauber und Fähigkeiten haben eine Chance, eine Bombe auf Euer Ziel abzufeuern, die sich in 5 kleinere Bomben aufteilt, wenn sie ihrem Ziel nahe ist. Beim Auftreffen auf dem Boden fügt jede der kleinen Bomben allen Gegnern in der Nähe 179 Schaden zu.\n\nErhöht Eure Ingenieurskunst von Kul Tiras oder Zandalar um 25." }
entries[282826] = { ["name"] = "Goblinischer Schockzauberschutz", ["text"] = "30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit 3 Kugelblitzen, die eine Chance von 50% gewähren, Nahkampf- oder Distanzangreifern Naturschaden zuzufügen. Jedes Mal, wenn der Blitzschlagschild ausgelöst wird, wird ein Kugelblitz verbraucht. Der Schild endet nach Ablauf von bis Abbruch oder nachdem er 3-mal ausgelöst wurde.\n(Procchance: 50%, 3s Abklingzeit)" }
entries[282827] = { ["name"] = "Pa'kus Zorn", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 8 sek.)\nDer Boss schleudert Federkiele auf alle Ziele, die alle 5.2 Sek. 46 körperlichen Schaden verursachen, und stößt sie alle zurück. Je weiter das Ziel vom Zaubernden entfernt ist, desto mehr Schaden erleidet es." }
