entries[282834] = { ["name"] = "Kimbuls Zorn", ["text"] = "100 Meter Reichweite\nSofort\nKimbul erscheint, springt auf zufällige Spielercharaktere zu, fügt so allen Gegnern innerhalb von 5 Metern 60 körperlichen Schaden zu und stößt sie zu Boden.\n\nZusätzlich werden alle Ziele mit ' Blutende Wunden ' belegt." }
